# frozen_string_literal: true

require_relative "../../plaid"

module Plaid
  module Types
    # Configures which LendScore variants are retrieved with the LendScore Complete product bundle. Omit when retrieving
    # a report generated by `/cra/report/create` or `/link/token/create`; the report is returned with the options it was
    # generated with.
    class CraReportGetLendScoreCompleteOptions < Internal::Types::Model
      field :variants, -> { Internal::Types::Array[Plaid::Types::CraLendScoreVariant] }, optional: true, nullable: false
    end
  end
end
